import re


def _datos_periodo(valor):
    """Convierte los códigos históricos de texto en claves institucionales estables."""
    original = (valor or '').strip().upper()
    compacto = re.sub(r'[^0-9A-Z]', '', original)
    coincidencia = re.match(r'^(?P<anio>\d{4})(?P<ciclo>[AB])(?P<sufijo>\d*)$', compacto)

    if coincidencia:
        anio = int(coincidencia.group('anio'))
        ciclo_base = coincidencia.group('ciclo')
        sufijo = coincidencia.group('sufijo')
        codigo = f'{anio}-{ciclo_base}{sufijo}'
        return {
            'codigo': codigo,
            'nombre': f'Período académico {codigo}',
            'anio_referencia': anio,
            'ciclo': 'E' if sufijo else ciclo_base,
            'tipo': 'extraordinario' if sufijo else 'ordinario',
        }

    coincidencia_anio = re.search(r'\d{4}', original)
    anio = int(coincidencia_anio.group()) if coincidencia_anio else 2000
    codigo = (original or f'{anio}-E')[:20]
    return {
        'codigo': codigo,
        'nombre': f'Período importado {codigo}',
        'anio_referencia': anio,
        'ciclo': 'E',
        'tipo': 'extraordinario',
    }


