    Vinculacion = apps.get_model('webcitt', 'VinculacionUsuarioPeriodo')

    valores = set(
        Catalogo.objects.exclude(periodo_academico='').values_list(
            'periodo_academico', flat=True
        )
    )
    valores.update(
        Reserva.objects.exclude(periodo_academico='').values_list(
            'periodo_academico', flat=True
        )
    )

    periodos_por_valor = {}
    for valor in valores:
        datos = _datos_periodo(valor)
        periodo, _ = Periodo.objects.get_or_create(
            codigo=datos['codigo'],
            defaults={
                **datos,
                'ambito': 'carreras_centros',
                'semanas_planificadas': 16,
                'estado': 'borrador',
                'observaciones': (
                    'Registro creado automáticamente desde el texto histórico '
                    'de actividades o reservas. Debe completarse con el calendario aprobado.'
                ),
            },
        )
        periodos_por_valor[valor] = periodo

    for valor, periodo in periodos_por_valor.items():
        Catalogo.objects.filter(periodo_academico=valor).update(
            periodo_id=periodo.pk,
            periodo_academico=periodo.codigo,
        )
        reservas = Reserva.objects.filter(periodo_academico=valor)
        reservas.update(periodo_id=periodo.pk, periodo_academico=periodo.codigo)

        for reserva in Reserva.objects.filter(
            periodo_id=periodo.pk
        ).exclude(usuario_id=None).iterator():
            Vinculacion.objects.get_or_create(
                usuario_id=reserva.usuario_id,
                periodo_id=periodo.pk,
                defaults={
                    'tipo_usuario': reserva.tipo_usuario_solicitante or 'externo',
                    'facultad': reserva.facultad_solicitante or '',
                    'carrera': reserva.carrera_solicitante or '',
                    'nivel_academico': reserva.nivel_academico_solicitante or '',
                    'institucion': reserva.institucion or '',
                    'estado': 'activa',
                    'fuente': 'importacion',
                    'validada': False,
                },
            )


